<?php require __DIR__.'/bootstrap.php';require __DIR__.'/webauthn.php';try{$v=webauthn_json();$challenge=$_SESSION['webauthn_login_challenge']??'';$uid=(int)($_SESSION['webauthn_login_user']??0);unset($_SESSION['webauthn_login_challenge'],$_SESSION['webauthn_login_user']);$rawId=b64u_decode($v['rawId']??'');$clientRaw=b64u_decode($v['response']['clientDataJSON']??'');$authRaw=b64u_decode($v['response']['authenticatorData']??'');$sig=b64u_decode($v['response']['signature']??'');if($rawId===false||$clientRaw===false||$authRaw===false||$sig===false)throw new RuntimeException('Resposta inválida');$client=json_decode($clientRaw,true);if(!is_array($client))throw new RuntimeException('ClientData inválido');webauthn_client_data($client,'webauthn.get',$challenge);$a=webauthn_auth_data($authRaw);if(($a['flags']&0x05)!==0x05||hash('sha256',webauthn_rp_id(),true)!==substr($authRaw,0,32))throw new RuntimeException('Biometria não confirmada');$q=$pdo->prepare('SELECT * FROM webauthn_credentials WHERE credential_id=? AND user_id=? LIMIT 1');$q->execute([$rawId,$uid]);$cred=$q->fetch();if(!$cred)throw new RuntimeException('Credencial desconhecida.');if($a['count']>0 && $a['count']<=(int)$cred['sign_count'])throw new RuntimeException('Contador de segurança inválido.');$signed=$authRaw.hash('sha256',$clientRaw,true);if(openssl_verify($signed,$sig,webauthn_public_pem($cred['public_key_x'],$cred['public_key_y']),OPENSSL_ALGO_SHA256)!==1)throw new RuntimeException('Assinatura biométrica inválida.');$pdo->prepare('UPDATE webauthn_credentials SET sign_count=?,last_used_at=NOW() WHERE id=?')->execute([$a['count'],$cred['id']]);session_regenerate_id(true);$_SESSION['arena_user']=$uid;$q=$pdo->prepare('SELECT role FROM users WHERE id=?');$q->execute([$uid]);$role=$q->fetchColumn();json_out(['ok'=>true,'redirect'=>in_array($role,['superadmin','publisher_admin','editor'],true)?'admin.php':'conta.php']);}catch(Throwable $e){json_out(['error'=>'Não foi possível validar a biometria.'],422);}
